    def __init__(self):
        self.complexity_metrics = {}
        self.recommendations = []

    def analyze_complexity(self, source_files):
        """
        Compute complexity metrics for each file/function.
        Uses abstract syntax trees (AST) for accurate analysis.
        """
        import ast
        for file, code in source_files.items():
            try:
                tree = ast.parse(code)
                metrics = self._compute_ast_metrics(tree)
                self.complexity_metrics[file] = metrics
            except SyntaxError as e:
                self.complexity_metrics[file] = {"error": str(e)}
        return self.complexity_metrics

    def _compute_ast_metrics(self, tree):
        """Helper: compute cyclomatic complexity, max nesting, and duplication risk."""
        complexity = 1  # base cyclomatic complexity
        max_nesting = 0
        node_counts = {}

        for node in ast.walk(tree):
            node_type = type(node).__name__
            node_counts[node_type] = node_counts.get(node_type, 0) + 1

            # Cyclomatic complexity: +1 for each decision point
            if isinstance(node, (ast.If, ast.While, ast.For, ast.ExceptHandler, ast.With)):
                complexity += 1
            elif isinstance(node, ast.BoolOp):
                complexity += len(node.values) - 1

            # Nesting depth
            if isinstance(node, (ast.If, ast.For, ast.While, ast.With, ast.Try)):
                depth = self._get_nesting_depth(node)
                max_nesting = max(max_nesting, depth)

        return {
            "cyclomatic_complexity": complexity,
            "max_nesting_depth": max_nesting,
            "node_distribution": node_counts,
            "risk_level": self._assess_risk(complexity, max_nesting)
        }

    def _get_nesting_depth(self, node, current_depth=0):
        """Recursively compute max nesting depth of a node."""
        max_depth = current_depth
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.If, ast.For, ast.While, ast.With, ast.Try)):
                max_depth = max(max_depth, self._get_nesting_depth(child, current_depth + 1))
        return max_depth

    def _assess_risk(self, complexity, nesting):
