# =============================================================================
# MACAO - Multi-Agent Code Analysis and Optimization System
# =============================================================================


class ModuleStatus(Enum):
    PENDING = "pending"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"


@dataclass
class FileMetrics:
    path: str
    lines: int
    complexity: int = 0
    coverage: float = 0.0
    nesting_depth: int = 0
    is_test: bool = False


@dataclass
class ProjectMetrics:
    total_files: int = 0
    total_lines: int = 0
    avg_complexity: float = 0.0
    avg_coverage: float = 0.0
    high_complexity_files: List[str] = field(default_factory=list)
    low_coverage_files: List[str] = field(default_factory=list)
    duplication_score: float = 0.0


# =============================================================================
# Utility Functions
# =============================================================================

def get_file_extension(path: str) -> str:
    return os.path.splitext(path)[1].lower()


def is_python_file(path: str) -> bool:
    return get_file_extension(path) in {".py"}


def is_test_file(path: str) -> bool:
    name = os.path.basename(path)
    return name.startswith("test_") or name.endswith("_test.py") or "test" in os.path.dirname(path).lower()


def calculate_cyclomatic_complexity(node: ast.AST) -> int:
    """Calculate cyclomatic complexity for an AST node."""
    complexity = 1
    for child in ast.walk(node):
        if isinstance(child, (ast.If, ast.While, ast.For, ast.ExceptHandler,
                              ast.With, ast.Assert, ast.comprehension)):
            complexity += 1
        elif isinstance(child, ast.BoolOp):
            complexity += len(child.values) - 1
    return complexity


def calculate_nesting_depth(node: ast.AST, current_depth: int = 0) -> int:
    """Calculate maximum nesting depth in an AST node."""
    max_depth = current_depth
    for child in ast.iter_child_nodes(node):
        if isinstance(child, (ast.If, ast.While, ast.For, ast.With, ast.Try)):
            max_depth = max(max_depth, calculate_nesting_depth(child, current_depth + 1))
        else:
            max_depth = max(max_depth, calculate_nesting_depth(child, current_depth))
    return max_depth


def estimate_lines_of_code(file_path: str) -> int:
    """Estimate lines of code (excluding blank and comments)."""
    try:
        with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()
        loc = 0
        in_multiline_comment = False
        for line in lines:
            stripped = line.strip()
            if in_multiline_comment:
                if '"""' in stripped or "'''" in stripped:
                    in_multiline_comment = False
                continue
            if stripped.startswith('"""') or stripped.startswith("'''"):
                if stripped.count('"""') == 1 or stripped.count("'''") == 1:
                    in_multiline_comment = True
                continue
            if stripped and not stripped.startswith('#'):
                loc += 1
        return loc
    except Exception:
        return 0


def run_coverage_analysis(file_path: str, test_file_path: Optional[str] = None) -> float:
    """Estimate coverage by checking if test functions exist for each public function."""
    try:
        with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
            source = f.read()
        tree = ast.parse(source)

        # Extract public functions/classes
        public_functions = []
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if not node.name.startswith('_'):
                    public_functions.append(node.name)
            elif isinstance(node, ast.ClassDef):
                if not node.name.startswith('_'):
                    public_functions.append(node.name)

        if not public_functions:
            return 100.0  # No public API to test

        # Try to find corresponding test file
        if test_file_path and os.path.exists(test_file_path):
            with open(test_file_path, 'r', encoding='utf-8', errors='ignore') as f:
                test_source = f.read()
            test_tree = ast.parse(test_source)
            tested_functions = set()
            for node in ast.walk(test_tree):
                if isinstance(node, ast.FunctionDef) and node.name.startswith('test_'):
                    # Extract function name being tested (e.g., test_add -> add)
                    func_name = node.name[5:] if node.name.startswith('test_') else node.name
                    tested_functions.add(func_name)

            covered = sum(1 for func in public_functions if func in tested_functions)
            return (covered / len(public_functions)) * 100.0
        else:
            # Fallback: assume 50% coverage if no test file found
            return 50.0
    except Exception:
        return 0.0


def detect_code_duplication(files: List[str]) -> float:
    """Estimate duplication by comparing hash signatures of function bodies."""
    if len(files) < 2:
        return 0.0

    function_signatures = []
    for file_path in files:
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                source = f.read()
            tree = ast.parse(source)
            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    # Create a simplified signature (name + line count + first line)
                    body_lines = ast.get_source_segment(source, node)
                    if body_lines:
                        sig = hashlib.md5(body_lines.encode()).hexdigest()[:8]
                        function_signatures.append(sig)
        except Exception:
            continue

    if len(function_signatures) < 2:
        return 0.0

    # Simple duplication: count duplicate signatures
    counts = defaultdict(int)
    for sig in function_signatures:
        counts[sig] += 1
    total = len(function_signatures)
    duplicated = sum(count for count in counts.values() if count > 1)
    return (duplicated / total) * 100.0 if total > 0 else 0.0


